    # line color = forms straight segments on borders; marker = scattered singles
    # determine: colors != bg; the one whose cells are all on border rows/cols -> line color
    nonbg=[c for c in cnt if c!=bg]
    pos={}
    for r in range(h):
        for c in range(w):
            if inp[r][c]!=bg: pos.setdefault(inp[r][c],[]).append((r,c))
    # line color: cells span a full row-run / col-run touching edge with length>1? use: exists a color with >=2 cells sharing a row or col consecutively aligned to edge
    def runs(col):
        # returns True if color col has a vertical run of len>=2 starting at row0 or ending at h-1
        cells=pos[col]
        rs=sorted(set(r for r,c in cells)); cs=sorted(set(c for r,c in cells))
        vert = len(cells)>=2 and (rs[0]==0 or rs[-1]==h-1) and all(c==cells[0][1] for r,c in cells)
        horz = len(cells)>=2 and (cs[0]==0 or cs[-1]==w-1) and all(r==cells[0][0] for r,c in cells)
        return vert or horz
    linec=[c for c in nonbg if runs(c)]
    linec=linec[0] if linec else None
    linecol=set(pos[linec])
    marker=[c for c in nonbg if c!=bg and c!=linec][0]
    out=[row[:] for row in inp]
    # connectors: markers emit ray toward line segment (whose span contains marker cross-coord), paint marker color, stop before segment; marker->4
    segs=[]
    cs=set(c for r,c in linecol)
    rs=set(r for r,c in linecol)
    # vertical segments grouped by column
    vseg={}
    for c in cs:
        rows_=sorted(r for r,c2 in linecol if c2==c)
        if len(rows_)>=2 and (rows_[0]==0 or rows_[-1]==h-1):
            vseg[c]=rows_
    hseg={}
    for r in rs:
        cols_=sorted(c for r2,c in linecol if r2==r)
        if len(cols_)>=2 and (cols_[0]==0 or cols_[-1]==w-1):
            hseg[r]=cols_
    for (mr,mc) in [(r,c) for r in range(h) for c in range(w) if inp[r][c]==marker]:
        out[mr][mc]=4
        painted=False
        # vertical segments
        for c,rows_ in vseg.items():
            if mr in rows_:
                step=1 if mc<c else -1
                cc=mc+step
                while 0<=cc<w and cc!=c:
                    if out[mr][cc]==bg: out[mr][cc]=marker
                    cc+=step
                painted=True
        # horizontal segments
        for r,cols_ in hseg.items():
            if mc in cols_:
                step=1 if mr<r else -1
                rr=mr+step
                while 0<=rr<h and rr!=r:
                    if out[rr][mc]==bg: out[rr][mc]=marker
                    rr+=step
                painted=True
        if not painted:
            # fallback: nearest segment endpoint Manhattan, straight L? leave as is (stay marker) -- rare
            pass
    # stamp: own band = band containing markers; partner band offset mapping -> full rows of marker color on bg cells
    # own band for vertical lines: rows span of the segment set containing markers' rows
    markrows=sorted(set(r for r,c in pos[marker]))
    # find segment column(s) whose row-span covers markrows
    own=None; par=None
    for c,rows_ in vseg.items():
        s,e_=min(rows_),max(rows_)
        if s<=markrows[0] and e_>=markrows[-1]:
            own=s; par=None
    # partner band: the other vertical segment's row span start
    parc=[c for c,rows_ in vseg.items() if c!=own or True]
    # partner = other segment column
    others=[c for c in vseg if c!=own][:1]
    par=[vseg[c][0] for c in others]
    p0=par[0]
    off=markrows[0]-own
    for r in range(h):
        if inp[r][0]==bg and 0<=r<h:
            pass
    # stamp rows: partner band rows = p0+off .. p0+len(markrows)-1, paint bg cells with marker color
    prange=[p0+i for i in range(len(markrows))]
    for r in prange:
        for c in range(w):
            if inp[r][c]==bg: out[r][c]=marker
    return out

